'use client';

/**
 * <RoxyGematria data={...} />: Gematria calculator that shows its work: every Hebrew spelling the input can take, the value under each cipher with the ones that are not single valued, the per letter breakdown right to left, the two substitution ciphers, the Latin alphabet ciphers and the curated words of equal value.
 *
 * You own this file. Customize freely. The component is re-exported from
 * @roxyapi/ui-react and stays in sync with the published package.
 *
 * Typical wiring (server-side fetch, client-side render):
 *
 * ```ts
 * // app/api/gematria/route.ts
 * import { createRoxy } from '@roxyapi/sdk';
 * const roxy = createRoxy(process.env.ROXY_API_KEY!);
 * export async function POST(req: Request) {
 *   const { data } = await roxy.someDomain.someMethod({ body: await req.json() });
 *   return Response.json(data);
 * }
 * ```
 *
 * Theme via --roxy-* CSS custom properties on :root (see globals.css).
 */
import { RoxyGematria as Element } from '@roxyapi/ui-react';
import type { ComponentProps } from 'react';

export type RoxyGematriaProps = ComponentProps<typeof Element>;

export function RoxyGematria(props: RoxyGematriaProps) {
	return <Element {...props} />;
}

export default RoxyGematria;
